  "test": "import logging
import pytest
import asyncio
from browser_use.browser.watchdogs.popups_watchdog import PopupsWatchdog

class DummyEvent:
    def __init__(self, target_id):
        self.target_id = target_id

class DummyPage:
    async def enable(self, *args, **kwargs):
        raise RuntimeError('enable failed')

class DummySend:
    Page = DummyPage()

class DummyRegisterPage:
    def javascriptDialogOpening(self, handler):
        pass

class DummyRegister:
    Page = DummyRegisterPage()

class DummyCDPClient:
    send = DummySend()
    register = DummyRegister()

class DummyCDPSession:
    def __init__(self):
        self.cdp_client = DummyCDPClient()
        self.session_id = 'sess123'

class DummyBrowserSession:
    async def get_or_create_cdp_session(self, target_id, focus=False):
        return DummyCDPSession()
    _cdp_client_root = None
    agent_focus_target_id = None

@pytest.mark.asyncio
async def test_failed_page_enable_logged_as_error(caplog):
    dummy_browser = DummyBrowserSession()
    watchdog = PopupsWatchdog()
    watchdog.browser_session = dummy_browser
    watchdog.logger = logging.getLogger('test_logger')
    caplog.set_level(logging.ERROR, logger='test_logger')
    event = DummyEvent('target1')
    await watchdog.on_TabCreatedEvent(event)
    assert any('Failed to enable Page domain' in rec.getMessage() for rec in caplog.records), "Error log for failed Page enable not found"
"
}
